import React, { useState } from 'react';
import '../styles/Profile.css';
import profilePhoto from '../img/mg.jpg'; // Импорт фотографии

function Profile() {
  const [user, setUser] = useState({
    name: 'Иван Иванов',
    gender: 'Мужской',
    birthDate: '01.01.1990',
    city: 'Москва',
    hobbies: ['Чтение', 'Баскетбол', 'Рисование', 'Игра на гитаре'],
    about: 'Привет! Я Иван, люблю заниматься спортом, рисовать и читать книги.',
    photo: profilePhoto,
  });

  function handleEditProfile() {
    alert("Функция редактирования профиля пока не реализована.");
  }

  return (
    <div className="profile">
      <div className="profile-photo">
        <img src={user.photo} alt="Профиль" />
        <button onClick={handleEditProfile} className="edit-button">Редактировать профиль</button>
      </div>
      <div className="profile-info">
        <h2>{user.name}</h2>
        <p><strong>Пол:</strong> {user.gender}</p>
        <p><strong>Дата рождения:</strong> {user.birthDate}</p>
        <p><strong>Город:</strong> {user.city}</p>
        <div>
          <strong>Хобби:</strong>
          <ul>
            {user.hobbies.map((hobby, index) => (
              <li key={index}>{hobby}</li>
            ))}
          </ul>
        </div>
        <div className="about">
          <strong>О себе:</strong>
          <p>{user.about}</p>
        </div>
      </div>
    </div>
  );
}

export default Profile;
